<script setup>
import { computed, onMounted, ref, watch } from 'vue'
import { ArrowRight, CalendarDays, ChartSpline, ShieldCheck, UsersRound } from 'lucide-vue-next'
import { useRoute } from 'vue-router'
import AnalyticsChart from '../components/charts/AnalyticsChart.vue'
import TeamPercentileProfile from '../components/analytics/TeamPercentileProfile.vue'
import SportIdentity from '../components/identity/SportIdentity.vue'
import SportCrumbs from '../components/navigation/SportCrumbs.vue'
import LoadingState from '../components/ui/LoadingState.vue'
import LoadError from '../components/ui/LoadError.vue'
import { entityRoute, metricValue, sentenceCase, sportLabel } from '../domain/sports'
import { sportById } from '../config/sports'
import { api } from '../services/api'
const props=defineProps({sport:{type:String,required:true}}),route=useRoute(),payload=ref(null),loading=ref(true),error=ref('')
const active=computed(()=>sportById(props.sport)),team=computed(()=>payload.value?.identity||{}),analytics=computed(()=>payload.value?.analytics||{}),roster=computed(()=>payload.value?.roster||[])
const trendSeries=computed(()=>Object.entries(analytics.value.trends||{}).filter(([key])=>key!=='labels').map(([key,values])=>({label:sentenceCase(key),values})))
const peerMetrics=computed(()=>analytics.value.metrics?.filter(metric=>Number.isFinite(Number(metric.percentile)))||[])
const record=computed(()=>{const s=payload.value?.standing;if(!s)return 'Record unavailable';return props.sport==='football'?`${s.wins||0}-${s.draws||0}-${s.losses||0} · ${s.points||0} pts`:`${s.wins||0}-${s.losses||0}`})
const load=async()=>{loading.value=true;error.value='';try{payload.value=await api.sportWorkspace(props.sport,'team',route.params.id,{competition:route.query.competition,discipline:route.query.discipline})}catch(caught){error.value=caught?.message||'The team workspace could not be loaded.'}finally{loading.value=false}}
watch(()=>[props.sport,route.params.id,route.query.competition],load);onMounted(load)
</script>
<style scoped>.analytics-grid.solo{grid-template-columns:1fr}</style>
<template><div class="team-view" :style="{'--sport':active.accent}"><LoadingState v-if="loading" label="Opening team intelligence" detail="Joining identity, roster, results and sport-specific analytics."/><LoadError v-else-if="error" :message="error" @retry="load"/><template v-else>
  <SportCrumbs :items="[{label:sportLabel(sport),to:active.route},{label:payload.league?.name||team.competition,to:payload.league?entityRoute(sport,'leagues',payload.league):`${active.route}/leagues`},{label:team.name}]"/>
  <section class="team-hero"><div class="team-brand"><SportIdentity :identity="team" :size="118" square/><div><span class="eyebrow">{{team.competition}} / {{team.country}}</span><h1>{{team.name}}<i>.</i></h1><p>{{team.venue}}<template v-if="team.formed"> · established {{team.formed}}</template></p></div></div><aside><span>CURRENT STATE</span><b>{{record}}</b><dl><div><dt>ROSTER</dt><dd>{{roster.length||'—'}}</dd></div><div><dt>UPCOMING</dt><dd>{{payload.games.upcoming.length}}</dd></div><div><dt>DATA GAMES</dt><dd>{{analytics.sample||0}}</dd></div></dl><RouterLink v-if="payload.league" :to="entityRoute(sport,'leagues',payload.league)">BACK TO {{payload.league.code}} <ArrowRight/></RouterLink></aside></section>
  <section class="state-grid"><article v-for="(metric,index) in analytics.metrics" :key="metric.label"><small>{{String(index+1).padStart(2,'0')}} · {{metric.unit}}</small><b>{{metricValue(metric.value,Number(metric.value)<1?3:1)}}</b><span>{{metric.label}}</span></article><article v-if="!analytics.metrics?.length" class="no-metrics"><ChartSpline/><b>Advanced team metrics unavailable</b><span>The source currently exposes identity and schedule evidence only.</span></article></section>
  <section class="analytics-grid" :class="{solo:!peerMetrics.length}"><article class="trend"><header><div><span class="eyebrow">PERFORMANCE TRAJECTORY</span><h2>{{sport==='basketball'?'Scoring and pace':sport==='football'?'Goals and chance volume':'Results over time'}}</h2></div><ChartSpline/></header><AnalyticsChart :labels="analytics.trends?.labels||[]" :series="trendSeries" :height="360"/><p>{{analytics.question}}</p></article><TeamPercentileProfile v-if="peerMetrics.length" :metrics="peerMetrics" :sample="analytics.peerSample||0" title="Where this team ranks"/></section>
  <section class="roster"><header><div><span class="eyebrow">NAVIGABLE ROSTER</span><h2>{{roster.length}} identified players</h2></div><UsersRound/></header><div v-if="roster.length" class="roster-grid"><RouterLink v-for="player in roster" :key="player.id" :to="entityRoute(sport,'players',player,{team:player.teamId||team.id,competition:team.competitionId,discipline:team.competitionId})"><div class="portrait"><SportIdentity :identity="player" :size="82" square/></div><span>{{player.position||'Player'}}<template v-if="player.number"> · #{{player.number}}</template></span><h3>{{player.name}}</h3><p>{{player.statistics?.pointsPerGame!=null?`${player.statistics.pointsPerGame.toFixed(1)} PPG · ${player.statistics.reboundsPerGame.toFixed(1)} RPG`:player.nationality||player.status||'Active roster'}}</p><ArrowRight/></RouterLink></div><div v-else class="empty"><UsersRound/><b>No provider-backed roster assignment is available.</b><p>Players without a verified team relationship are not shown as members of this roster.</p></div></section>
  <section class="schedule"><header><div><span class="eyebrow">TEAM CALENDAR</span><h2>Upcoming and recent</h2></div><CalendarDays/></header><div class="game-columns"><article><h3>NEXT</h3><RouterLink v-for="game in payload.games.upcoming" :key="game.id" :to="entityRoute(sport,'games',game,{competition:team.competitionId,discipline:team.competitionId})"><span>{{game.date}} · {{game.time}}</span><b>{{game.away?.name}} @ {{game.home?.name}}</b><em>{{game.venue}}</em></RouterLink><p v-if="!payload.games.upcoming.length">No upcoming event is in the current feed.</p></article><article><h3>RECENT</h3><RouterLink v-for="game in payload.games.recent" :key="game.id" :to="entityRoute(sport,'games',game,{competition:team.competitionId,discipline:team.competitionId})"><span>{{game.date}}</span><b>{{game.away?.name}} {{game.away?.score}}–{{game.home?.score}} {{game.home?.name}}</b><em>{{game.status}}</em></RouterLink><p v-if="!payload.games.recent.length">No recent result is in the current feed.</p></article></div></section>
</template></div></template>
<style scoped>.team-view{padding:18px 0 70px}.team-hero{min-height:430px;display:grid;grid-template-columns:1fr 340px;gap:65px;align-items:center;border-bottom:1px solid var(--line)}.team-brand{display:flex;align-items:center;gap:30px}.team-brand h1{max-width:920px;margin:12px 0;font-size:clamp(54px,8vw,112px);line-height:.83;letter-spacing:-.085em}.team-brand h1 i{font-style:normal;color:var(--sport)}.team-brand p{color:var(--muted);font-size:12px}.team-hero aside{min-height:270px;padding:23px;display:flex;flex-direction:column;background:var(--contrast);color:var(--on-contrast);border-top:4px solid var(--sport)}.team-hero aside>span{margin-top:auto;font:700 7px 'DM Mono';color:var(--sport)}.team-hero aside>b{margin:9px 0 18px;font-size:27px}.team-hero dl{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:#343a33}.team-hero dl div{padding:9px;background:#151915}.team-hero dt{font:600 6px 'DM Mono';color:#8d958a}.team-hero dd{margin:5px 0 0;font:800 16px 'DM Mono'}.team-hero aside a{display:flex;align-items:center;gap:7px;margin-top:17px;color:var(--on-contrast);font:700 7px 'DM Mono';text-decoration:none}.team-hero aside svg{width:14px;color:var(--sport)}.state-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:1px;margin:30px 0 12px;background:var(--line);border:1px solid var(--line)}.state-grid article{min-height:125px;padding:15px;display:flex;flex-direction:column;background:var(--surface)}.state-grid small{font:700 6px 'DM Mono';color:var(--muted)}.state-grid b{margin:auto 0 5px;font:800 24px 'DM Mono';color:var(--sport)}.state-grid span{font-size:9px}.state-grid .no-metrics{grid-column:1/-1;align-items:center;justify-content:center}.analytics-grid{display:grid;grid-template-columns:1.35fr .65fr;gap:12px}.trend,.profile,.roster,.schedule{border:1px solid var(--line);background:var(--surface)}.trend>header,.profile>header,.roster>header,.schedule>header{min-height:88px;padding:17px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line)}h2{margin:6px 0 0;font-size:28px;letter-spacing:-.05em}.trend>header svg,.roster>header svg,.schedule>header svg{color:var(--sport)}.trend>div{padding:14px}.trend>p{margin:0;padding:14px 18px;border-top:1px solid var(--line);font-size:11px;line-height:1.65}.profile>header{display:block}.profile>div{display:grid;gap:22px;padding:20px}.roster,.schedule{margin-top:12px}.roster-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:1px;background:var(--line)}.roster-grid a{min-width:0;min-height:285px;position:relative;padding:13px;display:flex;flex-direction:column;background:var(--surface);text-decoration:none}.portrait{height:145px;display:grid;place-items:center;overflow:hidden;background:var(--raised)}.portrait img{width:100%;height:100%;object-fit:contain;object-position:center bottom}.roster-grid a>span{margin-top:13px;font:700 7px 'DM Mono';color:var(--sport)}.roster-grid h3{margin:7px 0 4px;font-size:14px}.roster-grid p{margin:0;color:var(--muted);font-size:8px}.roster-grid a>svg{position:absolute;right:13px;bottom:13px;width:15px}.game-columns{display:grid;grid-template-columns:1fr 1fr;gap:1px;background:var(--line)}.game-columns article{background:var(--surface)}.game-columns h3{padding:13px;margin:0;border-bottom:1px solid var(--line);font:800 8px 'DM Mono';color:var(--sport)}.game-columns a{min-height:68px;padding:11px 13px;display:grid;grid-template-columns:110px 1fr auto;align-items:center;gap:12px;border-bottom:1px solid var(--line);text-decoration:none}.game-columns a span,.game-columns a em{font:600 7px 'DM Mono';font-style:normal;color:var(--muted)}.game-columns a b{font-size:10px}.game-columns article>p{padding:25px;color:var(--muted);font-size:9px}.empty{min-height:210px;display:grid;place-items:center;align-content:center;text-align:center;gap:8px;color:var(--muted)}.empty b{color:var(--text)}.empty p{max-width:460px;margin:0;font-size:8px;line-height:1.6}@media(max-width:1100px){.team-hero{grid-template-columns:1fr;padding:45px 0}.state-grid{grid-template-columns:repeat(3,1fr)}.analytics-grid{grid-template-columns:1fr}.roster-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:760px){.team-brand{align-items:flex-start;flex-direction:column}.roster-grid{grid-template-columns:repeat(2,1fr)}.game-columns{grid-template-columns:1fr}.game-columns a{grid-template-columns:85px 1fr}.game-columns a em{display:none}}@media(max-width:480px){.state-grid{grid-template-columns:repeat(2,1fr)}.roster-grid{grid-template-columns:1fr 1fr}.portrait{height:125px}.roster-grid a{min-height:250px}}</style>
